export const envelope = [38, 14, 15];

export default function build(api) {
  const { size } = api;
  const seatY = 3;

  // Safe theme extraction with thematic medieval fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const roofStairs = api.theme?.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme?.roof?.slab || "minecraft:dark_oak_slab";

  const groundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";
  const groundRevetment = api.theme?.ground?.revetment || "minecraft:mossy_stone_bricks";

  function withState(blockStr, stateStr) {
    if (!blockStr) return blockStr;
    const base = blockStr.split("[")[0];
    return `${base}[${stateStr}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  // Deterministic coordinate hash for masonry aging
  function hash(x, y, z) {
    let h = (x * 374761393 + y * 668265263 + z * 3628273) ^ 0x5bf03635;
    h = Math.imul(h ^ (h >>> 16), 2246822519);
    return (h ^ (h >>> 13)) >>> 0;
  }

  // =========================================================================
  // 1. WEST QUAY & PIER (Stone Village Shore, X: 0..7, Z: 2..12)
  // =========================================================================
  for (let x = 0; x <= 7; x++) {
    for (let z = 2; z <= 12; z++) {
      const h = api.heightAt(x, z);
      const gy = Math.max(0, Math.min(10, seatY + h));

      if (gy <= 4) {
        // Foundation course from seabed/ground to deck level
        for (let y = gy; y <= 3; y++) {
          if (y === gy) {
            setBlock(x, y, z, groundRevetment);
          } else {
            const hVal = hash(x, y, z) % 3;
            setBlock(x, y, z, hVal === 0 ? stonePrimary : (hVal === 1 ? stoneAccent : groundRevetment));
          }
        }

        // Quay deck at Y = 4
        if (x === 7) {
          if (z === 3 || z === 4 || z === 10 || z === 11) {
            // Steps down to water level
            setBlock(x, 3, z, withState(stoneStairs, "facing=east,half=top"));
            setBlock(x, 4, z, withState(stoneStairs, "facing=east,half=bottom"));
          } else if (z === 2 || z === 12) {
            // Mooring bollards
            setBlock(x, 4, z, stonePrimary);
            setBlock(x, 5, z, stoneWall);
            setBlock(x, 6, z, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
          } else {
            setBlock(x, 4, z, stonePrimary);
          }
        } else {
          setBlock(x, 4, z, hash(x, 4, z) % 2 === 0 ? groundPavement : stonePrimary);
        }
      } else {
        // Rising ground on hillside tests: construct masonry retaining slope
        for (let y = 3; y <= gy; y++) {
          setBlock(x, y, z, hash(x, y, z) % 2 === 0 ? stonePrimary : stoneAccent);
        }
        setBlock(x, gy, z, groundPavement);
      }
    }
  }

  // Mooring chains hanging down quay edge
  setBlock(7, 3, 2, "minecraft:chain[axis=y]");
  setBlock(7, 2, 2, "minecraft:chain[axis=y]");
  setBlock(7, 3, 12, "minecraft:chain[axis=y]");
  setBlock(7, 2, 12, "minecraft:chain[axis=y]");

  // =========================================================================
  // 2. WEST STONE WINCH BASTION (X: 1..5, Z: 5..9, Y: 4..10)
  // =========================================================================
  // Heavy corner pillars
  const westPillars = [[1, 5], [1, 9], [5, 5], [5, 9]];
  for (const [px, pz] of westPillars) {
    for (let y = 4; y <= 8; y++) {
      setBlock(px, y, pz, stonePrimary);
    }
    setBlock(px, 9, pz, stoneWall);
  }

  // North & South walls
  for (let x = 2; x <= 4; x++) {
    for (let y = 5; y <= 7; y++) {
      setBlock(x, y, 5, (x === 3 && y === 6) ? stoneWall : stonePrimary);
      setBlock(x, y, 9, (x === 3 && y === 6) ? stoneWall : stonePrimary);
    }
  }

  // West solid wall
  for (let z = 6; z <= 8; z++) {
    for (let y = 5; y <= 8; y++) {
      setBlock(1, y, z, (z === 7 && y === 6) ? stoneWall : stonePrimary);
    }
  }

  // East wall / Fjord opening archway
  for (let y = 5; y <= 6; y++) {
    setBlock(5, y, 6, stonePrimary);
    setBlock(5, y, 8, stonePrimary);
  }
  setBlock(5, 7, 6, withState(stoneStairs, "facing=south,half=top"));
  setBlock(5, 7, 8, withState(stoneStairs, "facing=north,half=top"));
  setBlock(5, 7, 7, withState(stoneSlab, "type=top"));

  // Stone corbelled roof eaves
  for (let x = 1; x <= 5; x++) {
    setBlock(x, 9, 5, withState(roofStairs, "facing=north,half=bottom"));
    setBlock(x, 9, 9, withState(roofStairs, "facing=south,half=bottom"));
  }
  for (let z = 6; z <= 8; z++) {
    setBlock(1, 9, z, withState(roofStairs, "facing=west,half=bottom"));
    setBlock(5, 9, z, withState(roofStairs, "facing=east,half=bottom"));
  }
  for (let x = 2; x <= 4; x++) {
    setBlock(x, 9, 6, stonePrimary);
    setBlock(x, 9, 8, stonePrimary);
    setBlock(x, 9, 7, stonePrimary);
    setBlock(x, 10, 7, withState(roofSlab, "type=bottom"));
  }

  // Internal Stone Winch Mechanism
  setBlock(2, 6, 7, withState(woodLog, "axis=x"));
  setBlock(3, 6, 7, withState(woodStripped, "axis=x"));
  setBlock(4, 6, 7, withState(woodLog, "axis=x"));
  setBlock(2, 6, 6, withState(woodTrapdoor, "facing=west,half=top,open=false"));
  setBlock(2, 6, 8, withState(woodTrapdoor, "facing=west,half=top,open=false"));
  setBlock(3, 7, 7, "minecraft:lantern[hanging=true]");

  // Cable exit mount
  setBlock(5, 8, 6, stoneWall);
  setBlock(5, 8, 8, stoneWall);
  setBlock(5, 8, 7, withState(stoneSlab, "type=top"));

  // =========================================================================
  // 3. MAIN HAWSER CABLE (Spanning X: 5..32 at Z: 7, Y: 8)
  // =========================================================================
  for (let x = 5; x <= 32; x++) {
    setBlock(x, 8, 7, "minecraft:chain[axis=x]");
  }
  // Cable tension drops
  setBlock(10, 9, 7, "minecraft:chain[axis=y]");
  setBlock(27, 9, 7, "minecraft:chain[axis=y]");

  // =========================================================================
  // 4. THE HEAVY FERRY RAFT (X: 14..22, Z: 4..10)
  // =========================================================================
  // Pontoon Hull (Y = 2)
  for (let x = 15; x <= 21; x++) {
    setBlock(x, 2, 5, withState(woodLog, "axis=x"));
    setBlock(x, 2, 7, withState(woodLog, "axis=x"));
    setBlock(x, 2, 9, withState(woodLog, "axis=x"));
  }
  // Pointed prow/stern ends
  setBlock(14, 2, 5, withState(woodStairs, "facing=west,half=bottom"));
  setBlock(14, 2, 7, withState(woodStairs, "facing=west,half=bottom"));
  setBlock(14, 2, 9, withState(woodStairs, "facing=west,half=bottom"));
  setBlock(22, 2, 5, withState(woodStairs, "facing=east,half=bottom"));
  setBlock(22, 2, 7, withState(woodStairs, "facing=east,half=bottom"));
  setBlock(22, 2, 9, withState(woodStairs, "facing=east,half=bottom"));

  // Cross ribs under the deck
  for (const rx of [16, 18, 20]) {
    for (let z = 4; z <= 10; z++) {
      setBlock(rx, 2, z, woodPlanks);
    }
  }

  // Raft Decking (Y = 3)
  for (let x = 15; x <= 21; x++) {
    for (let z = 4; z <= 10; z++) {
      if (z === 4 || z === 10) {
        setBlock(x, 3, z, withState(woodStripped, "axis=x"));
      } else {
        setBlock(x, 3, z, woodPlanks);
      }
    }
  }
  // Boarding ramps on West & East ends
  for (let z = 6; z <= 8; z++) {
    setBlock(14, 3, z, withState(woodStairs, "facing=east,half=bottom"));
    setBlock(22, 3, z, withState(woodStairs, "facing=west,half=bottom"));
  }

  // Safety Railings & Benches (Y = 4)
  for (let x = 15; x <= 21; x++) {
    if (x !== 17 && x !== 19) {
      setBlock(x, 4, 4, woodFence);
      setBlock(x, 4, 10, woodFence);
    }
  }
  // Passenger benches
  for (const bx of [15, 16, 20, 21]) {
    setBlock(bx, 4, 5, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(bx, 4, 9, withState(woodStairs, "facing=north,half=bottom"));
  }

  // Deck details
  setBlock(15, 4, 7, withState(woodLog, "axis=y"));
  setBlock(16, 4, 7, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
  setBlock(21, 4, 7, woodFence);
  setBlock(22, 5, 7, withState(woodTrapdoor, "facing=east,half=top,open=true"));

  // Overhead Guide Gantry (X: 17..19, Z: 4..10, Y: 4..9)
  for (let y = 4; y <= 8; y++) {
    setBlock(17, y, 4, withState(woodStripped, "axis=y"));
    setBlock(19, y, 4, withState(woodStripped, "axis=y"));
    setBlock(17, y, 10, withState(woodStripped, "axis=y"));
    setBlock(19, y, 10, withState(woodStripped, "axis=y"));
  }
  setBlock(17, 7, 5, withState(woodStairs, "facing=south,half=top"));
  setBlock(19, 7, 5, withState(woodStairs, "facing=south,half=top"));
  setBlock(17, 7, 9, withState(woodStairs, "facing=north,half=top"));
  setBlock(19, 7, 9, withState(woodStairs, "facing=north,half=top"));

  // Overhead crossbeams (Y = 8)
  for (let z = 5; z <= 9; z++) {
    setBlock(17, 8, z, woodFence);
    setBlock(19, 8, z, woodFence);
  }
  setBlock(18, 8, 4, withState(woodStripped, "axis=y"));
  setBlock(18, 8, 5, withState(woodStairs, "facing=south,half=top"));
  setBlock(18, 8, 6, woodPlanks);
  // (18, 8, 7) is the hawser cable passing through
  setBlock(18, 8, 8, woodPlanks);
  setBlock(18, 8, 9, withState(woodStairs, "facing=north,half=top"));
  setBlock(18, 8, 10, withState(woodStripped, "axis=y"));

  // Pulley Sheave assembly over the cable (Y = 9..10)
  setBlock(18, 9, 6, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(18, 9, 7, "minecraft:iron_bars");
  setBlock(18, 9, 8, withState(woodStairs, "facing=north,half=bottom"));
  setBlock(18, 10, 7, withState(woodSlab, "type=bottom"));

  // Raft hand-crank windlass & vertical drive chain
  setBlock(18, 4, 7, withState(woodStripped, "axis=z"));
  setBlock(18, 4, 6, withState(woodTrapdoor, "facing=north,half=top,open=false"));
  setBlock(18, 4, 8, withState(woodTrapdoor, "facing=south,half=top,open=false"));
  setBlock(18, 5, 7, "minecraft:chain[axis=y]");
  setBlock(18, 6, 7, "minecraft:chain[axis=y]");
  setBlock(18, 7, 7, "minecraft:chain[axis=y]");

  // Gantry lanterns
  setBlock(18, 7, 5, "minecraft:lantern[hanging=true]");
  setBlock(18, 7, 9, "minecraft:lantern[hanging=true]");

  // =========================================================================
  // 5. EAST TIMBER STILT DOCK (Timber Village Shore, X: 29..37, Z: 2..12)
  // =========================================================================
  const eastPilingX = [29, 32, 35, 37];
  const eastPilingZ = [2, 5, 7, 9, 12];

  for (const px of eastPilingX) {
    for (const pz of eastPilingZ) {
      const h = api.heightAt(px, pz);
      const gy = Math.max(0, Math.min(10, seatY + h));
      for (let y = gy; y <= 3; y++) {
        setBlock(px, y, pz, withState(woodLog, "axis=y"));
      }
    }
  }

  // Cross-bracing between stilts at Y = 3
  for (const px of [29, 32, 35]) {
    for (let z = 3; z <= 11; z++) {
      if (!eastPilingZ.includes(z)) {
        setBlock(px, 3, z, woodFence);
      }
    }
  }

  // Dock Decking at Y = 4
  for (let x = 29; x <= 37; x++) {
    for (let z = 2; z <= 12; z++) {
      const h = api.heightAt(x, z);
      const gy = Math.max(0, Math.min(10, seatY + h));

      if (gy > 4) {
        // Hillside interface
        for (let y = 3; y <= gy; y++) {
          setBlock(x, y, z, withState(woodLog, "axis=y"));
        }
        setBlock(x, gy, z, woodPlanks);
      } else {
        setBlock(x, 4, z, woodPlanks);
      }
    }
  }

  // Dock curbs & edge trim
  for (let x = 29; x <= 37; x++) {
    setBlock(x, 4, 2, withState(woodStripped, "axis=x"));
    setBlock(x, 4, 12, withState(woodStripped, "axis=x"));
  }
  for (let z = 2; z <= 12; z++) {
    setBlock(29, 4, z, withState(woodStripped, "axis=z"));
  }

  // Mooring bits on dock
  const dockBollards = [[29, 2], [29, 12], [37, 2], [37, 12]];
  for (const [bx, bz] of dockBollards) {
    setBlock(bx, 5, bz, woodFence);
    setBlock(bx, 6, bz, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
  }

  // Boarding ladders down to water
  setBlock(29, 3, 3, withState(woodStairs, "facing=east,half=bottom"));
  setBlock(29, 3, 11, withState(woodStairs, "facing=east,half=bottom"));

  // Fish drying rack on north dock rail
  setBlock(30, 5, 2, woodFence);
  setBlock(32, 5, 2, woodFence);
  setBlock(31, 5, 2, withState(woodTrapdoor, "facing=south,half=top,open=false"));
  setBlock(30, 6, 2, woodFence);
  setBlock(31, 6, 2, woodFence);
  setBlock(32, 6, 2, woodFence);

  // Lantern post on south dock
  setBlock(30, 5, 12, woodFence);
  setBlock(30, 6, 12, woodFence);
  setBlock(30, 7, 12, woodFence);
  setBlock(30, 7, 11, woodFence);
  setBlock(30, 6, 11, "minecraft:lantern[hanging=true]");

  // =========================================================================
  // 6. EAST TIMBER WINCH HOUSE (X: 31..35, Z: 5..9, Y: 4..13)
  // =========================================================================
  // 4 Main corner posts
  const eastWinchPosts = [[31, 5], [31, 9], [35, 5], [35, 9]];
  for (const [px, pz] of eastWinchPosts) {
    for (let y = 4; y <= 10; y++) {
      setBlock(px, y, pz, withState(woodStripped, "axis=y"));
    }
  }

  // Girth crossbeams at Y = 8 and Y = 10
  for (const y of [8, 10]) {
    for (let x = 31; x <= 35; x++) {
      setBlock(x, y, 5, withState(woodLog, "axis=x"));
      setBlock(x, y, 9, withState(woodLog, "axis=x"));
    }
    for (let z = 5; z <= 9; z++) {
      setBlock(31, y, z, withState(woodLog, "axis=z"));
      setBlock(35, y, z, withState(woodLog, "axis=z"));
    }
  }

  // Pitched Nordic timber roof (Y: 11..13)
  for (let x = 30; x <= 36; x++) {
    // North roof slope
    setBlock(x, 11, 4, withState(roofStairs, "facing=north,half=bottom"));
    setBlock(x, 12, 5, withState(roofStairs, "facing=north,half=bottom"));
    setBlock(x, 12, 6, roofSlab);

    // South roof slope
    setBlock(x, 11, 10, withState(roofStairs, "facing=south,half=bottom"));
    setBlock(x, 12, 9, withState(roofStairs, "facing=south,half=bottom"));
    setBlock(x, 12, 8, roofSlab);

    // Central Ridge
    setBlock(x, 13, 7, withState(roofSlab, "type=bottom"));
  }

  // Gable end screens
  for (const gx of [31, 35]) {
    setBlock(gx, 11, 6, woodPlanks);
    setBlock(gx, 11, 7, woodFence);
    setBlock(gx, 11, 8, woodPlanks);
    setBlock(gx, 12, 7, woodPlanks);
  }

  // Internal Timber Windlass Machinery
  setBlock(33, 6, 6, withState(woodLog, "axis=z"));
  setBlock(33, 6, 7, withState(woodLog, "axis=z"));
  setBlock(33, 6, 8, withState(woodLog, "axis=z"));

  // Capstan turning spokes
  setBlock(33, 7, 7, woodFence);
  setBlock(33, 5, 7, woodFence);
  setBlock(32, 6, 7, woodFence);
  setBlock(34, 6, 7, woodFence);

  // Ballast weight box
  setBlock(35, 5, 7, withState(woodStripped, "axis=y"));
  setBlock(35, 6, 7, withState(woodStripped, "axis=y"));

  // Cable anchor & guide pulleys
  setBlock(32, 8, 6, withState(woodTrapdoor, "facing=west,half=top,open=false"));
  setBlock(32, 8, 8, withState(woodTrapdoor, "facing=west,half=top,open=false"));
  setBlock(32, 8, 7, "minecraft:chain[axis=x]");
  setBlock(33, 8, 7, "minecraft:chain[axis=y]");

  // Winch house interior lantern
  setBlock(33, 11, 7, "minecraft:lantern[hanging=true]");

  return {
    name: "rope_ferry",
    seatY: seatY,
    anchors: {
      front: [18, 4, 0],
      west_landing: [0, 4, 7],
      east_landing: [37, 4, 7],
      ferry_raft: [18, 4, 7],
    },
  };
}

