export const envelope = [9, 13, 8];

export default function build(api) {
  const { theme, instance } = api;
  const rng = api.random;
  const idx = instance.index;

  // Helpers to safely apply block states to theme strings
  function state(block, props) {
    if (!block) return "minecraft:spruce_planks";
    const base = block.includes("[") ? block.slice(0, block.indexOf("[")) : block;
    return `${base}[${props}]`;
  }

  const logY = state(theme.wood.log, "axis=y");
  const logX = state(theme.wood.log, "axis=x");
  const logZ = state(theme.wood.log, "axis=z");
  const strippedX = state(theme.wood.stripped || theme.wood.log, "axis=x");
  const strippedY = state(theme.wood.stripped || theme.wood.log, "axis=y");

  const planks = theme.wood.planks;
  const fence = theme.wood.fence;
  const slabBottom = state(theme.wood.slab, "type=bottom");
  const slabTop = state(theme.wood.slab, "type=top");

  const stonePlinth = theme.ground.plinth || theme.stone.primary;
  const stonePave = theme.ground.pavement || theme.stone.primary;
  const stoneSlab = state(theme.stone.slab || theme.wood.slab, "type=bottom");

  // Voxel storage for deterministic rendering and 6-connectivity guarantees
  const voxels = new Map();

  function set(x, y, z, block) {
    if (x < 0 || x >= envelope[0] || y < 0 || y >= envelope[1] || z < 0 || z >= envelope[2]) {
      return;
    }
    const key = (x << 16) | (y << 8) | z;
    voxels.set(key, { x, y, z, block });
  }

  function get(x, y, z) {
    const key = (x << 16) | (y << 8) | z;
    return voxels.get(key);
  }

  // Architectural style variations across 12 instances
  const style = idx % 4; // 0: Grand Lofoten Hjell, 1: Shore Salt-Shed, 2: Deep Stilt Wharf, 3: High Wind Scaffold
  const fishDensity = 0.55 + (idx * 0.035) % 0.4;
  const ladderX = style === 1 ? 7 : (style === 2 ? 1 : 4);
  const hasRearLeanTo = style === 1 || style === 2;
  const highTierShelter = style === 0 || style === 3;

  const seatY = 3;

  // 1. Terrain following foundations & ballast stone piers
  // Main bent X lines: 1, 4, 7
  const bentsX = [1, 4, 7];
  const postZ = [1, 3, 4, 6];

  for (const bx of bentsX) {
    for (const bz of postZ) {
      const gh = Math.round(api.heightAt(bx, bz));
      const groundY = Math.max(0, Math.min(seatY, seatY + gh));

      // Build foundation pier down to local ground
      for (let y = groundY; y <= seatY; y++) {
        if (y <= 1) {
          set(bx, y, bz, stonePlinth);
          // Stone ballast footing expansion
          if (bx > 0 && y === groundY) set(bx - 1, y, bz, stonePave);
          if (bx < 8 && y === groundY) set(bx + 1, y, bz, stonePave);
        } else {
          set(bx, y, bz, logY);
        }
      }

      // If uphill terrain rises above seat plane, seat properly on it
      if (gh > 0) {
        const topH = Math.min(6, seatY + gh);
        for (let y = seatY + 1; y <= topH; y++) {
          set(bx, y, bz, stonePlinth);
        }
      }
    }
  }

  // Continuous foundation beams & under-deck joists (y = 2)
  for (let x = 1; x <= 7; x++) {
    for (const z of [1, 3, 4, 6]) {
      if (!get(x, 2, z)) set(x, 2, z, logX);
    }
  }
  for (const bx of bentsX) {
    for (let z = 1; z <= 6; z++) {
      if (!get(bx, 2, z)) set(bx, 2, z, logZ);
    }
  }

  // 2. Timber Processing Deck & Wharf Boardwalk (y = 3)
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 6; z++) {
      // Create slight weathering gaps or trapdoor hatch based on PRNG
      const isHatch = (x === 2 && z === 5 && idx % 2 === 0);
      const isWornSlab = ((x + z + idx) % 7 === 0);

      if (isHatch) {
        set(x, 3, z, state(theme.wood.trapdoor, "facing=north,half=bottom,open=false"));
      } else if (isWornSlab) {
        set(x, 3, z, slabBottom);
      } else {
        set(x, 3, z, planks);
      }
    }
  }

  // Perimeter bumper kerb logs on the front approach (z = 1) and rear (z = 6)
  for (let x = 0; x <= 8; x++) {
    set(x, 3, 1, logX);
    set(x, 3, 6, logX);
  }

  // 3. A-Frame Bents (Transverse frames at x = 1, 4, 7)
  for (const bx of bentsX) {
    // Lower tier posts (y = 4..5)
    set(bx, 4, 1, logY);
    set(bx, 5, 1, logY);
    set(bx, 4, 6, logY);
    set(bx, 5, 6, logY);

    // Mid cross tie beam at y = 5
    for (let z = 1; z <= 6; z++) {
      set(bx, 5, z, logZ);
    }

    // Diagonal knee braces under cross tie (y = 4)
    set(bx, 4, 2, state(theme.wood.stairs, "facing=north,half=top"));
    set(bx, 4, 5, state(theme.wood.stairs, "facing=south,half=top"));

    // Mid tier posts stepping inwards (y = 6..8)
    for (let y = 6; y <= 8; y++) {
      set(bx, y, 2, logY);
      set(bx, y, 5, logY);
    }

    // Mid cross tie collar beam at y = 8
    for (let z = 2; z <= 5; z++) {
      set(bx, 8, z, logZ);
    }
    set(bx, 7, 3, state(theme.wood.stairs, "facing=north,half=top"));
    set(bx, 7, 4, state(theme.wood.stairs, "facing=south,half=top"));

    // High tier posts converging toward apex (y = 9..11)
    for (let y = 9; y <= 11; y++) {
      set(bx, y, 3, logY);
      set(bx, y, 4, logY);
    }

    // High collar tie beam at y = 11
    set(bx, 11, 3, logZ);
    set(bx, 11, 4, logZ);

    // Apex rafters / peak cap at y = 12
    set(bx, 12, 3, state(theme.wood.stairs, "facing=south,half=bottom"));
    set(bx, 12, 4, state(theme.wood.stairs, "facing=north,half=bottom"));
  }

  // 4. Longitudinal Drying Rails (Poles spanning full width across X)
  for (let x = 0; x <= 8; x++) {
    // Tier 1 rails (y = 5)
    set(x, 5, 1, strippedX);
    set(x, 5, 6, strippedX);

    // Tier 2 rails (y = 7)
    set(x, 7, 2, fence);
    set(x, 7, 5, fence);

    // Tier 3 rails (y = 9)
    set(x, 9, 2, fence);
    set(x, 9, 5, fence);
    set(x, 9, 3, strippedX);
    set(x, 9, 4, strippedX);

    // Tier 4 high rails (y = 11)
    set(x, 11, 3, strippedX);
    set(x, 11, 4, strippedX);

    // Ridge pole along the peak (y = 12)
    set(x, 12, 3, logX);
    set(x, 12, 4, logX);
  }

  // Catwalk on Tier 2 for inspecting and hanging fish (y = 6, z = 3..4)
  for (let x = 1; x <= 7; x++) {
    set(x, 6, 3, planks);
    set(x, 6, 4, planks);
  }

  // Rear lean-to drying canopy / salt shed roof (when active)
  if (hasRearLeanTo) {
    for (let x = 0; x <= 8; x++) {
      set(x, 8, 5, state(theme.wood.stairs, "facing=north,half=bottom"));
      set(x, 7, 6, state(theme.wood.stairs, "facing=north,half=bottom"));
      set(x, 6, 7, state(theme.wood.stairs, "facing=north,half=bottom"));
      // Support posts along rear edge
      if (x === 1 || x === 4 || x === 7) {
        set(x, 4, 7, fence);
        set(x, 5, 7, fence);
      }
    }
  }

  if (highTierShelter) {
    for (let x = 0; x <= 8; x++) {
      set(x, 10, 2, state(theme.wood.stairs, "facing=south,half=bottom"));
      set(x, 10, 5, state(theme.wood.stairs, "facing=north,half=bottom"));
    }
  }

  // 5. Stockfish Fillets / Dried Cod Pairs (Hanging beneath rails)
  const fishTypes = [
    "minecraft:birch_trapdoor[facing=north,half=top,open=true]",
    "minecraft:birch_trapdoor[facing=south,half=top,open=true]",
    "minecraft:birch_slab[type=top]",
    "minecraft:birch_fence",
    state(theme.wood.trapdoor, "facing=north,half=top,open=true"),
    state(theme.wood.slab, "type=top")
  ];

  function hangFish(x, y, z, rVal) {
    if (rVal < fishDensity && !get(x, y, z)) {
      const typeIdx = Math.floor(rVal * 17) % fishTypes.length;
      set(x, y, z, fishTypes[typeIdx]);
    }
  }

  for (let x = 0; x <= 8; x++) {
    // Under Tier 1 rails (y = 4)
    hangFish(x, 4, 1, ((x * 7 + idx * 3) % 100) / 100);
    hangFish(x, 4, 6, ((x * 11 + idx * 5) % 100) / 100);

    // Under Tier 2 rails (y = 6)
    hangFish(x, 6, 2, ((x * 13 + idx * 7) % 100) / 100);
    hangFish(x, 6, 5, ((x * 17 + idx * 11) % 100) / 100);

    // Under Tier 3 rails (y = 8)
    hangFish(x, 8, 2, ((x * 19 + idx * 13) % 100) / 100);
    hangFish(x, 8, 5, ((x * 23 + idx * 17) % 100) / 100);
    hangFish(x, 8, 3, ((x * 29 + idx * 19) % 100) / 100);
    hangFish(x, 8, 4, ((x * 31 + idx * 23) % 100) / 100);

    // Under Tier 4 high rails (y = 10)
    hangFish(x, 10, 3, ((x * 37 + idx * 29) % 100) / 100);
    hangFish(x, 10, 4, ((x * 41 + idx * 31) % 100) / 100);
  }

  // 6. Access Ladders to Catwalk
  const ladFacing = ladderX === 7 ? "facing=west" : (ladderX === 1 ? "facing=east" : "facing=south");
  const ladZ = ladderX === 4 ? 2 : 3;
  for (let y = 4; y <= 6; y++) {
    set(ladderX, y, ladZ, `minecraft:ladder[${ladFacing}]`);
  }

  // 7. Salted Barrels, Fish Boxes, Brine Cauldron, and Rope Coils on the Deck (y = 4..5)
  // Stacked salted fish barrels cluster A (x = 2..3, z = 2..3)
  set(2, 4, 2, "minecraft:barrel[facing=up]");
  if (style !== 3) {
    set(2, 5, 2, "minecraft:barrel[facing=up]");
  } else {
    set(2, 5, 2, slabBottom);
  }
  set(3, 4, 2, "minecraft:barrel[facing=north]");

  // Salted barrels cluster B (x = 5..6, z = 4..5)
  set(6, 4, 4, "minecraft:barrel[facing=up]");
  set(6, 4, 5, "minecraft:barrel[facing=east]");
  if (style === 0 || style === 2) {
    set(6, 5, 4, "minecraft:barrel[facing=up]");
  }

  // Salt brine tub / fish curing cauldron
  const vatX = style % 2 === 0 ? 5 : 2;
  const vatZ = style % 2 === 0 ? 2 : 4;
  set(vatX, 4, vatZ, "minecraft:cauldron");

  // Fish gutting & filleting bench with stone top
  const tableX = style === 1 ? 3 : 5;
  set(tableX, 4, 3, fence);
  set(tableX, 5, 3, stoneSlab);

  // Rope coils & dried hemp tackle bundles (hay blocks with axis alignment)
  set(5, 4, 5, "minecraft:hay_block[axis=y]");
  set(5, 5, 5, slabBottom);
  if (style >= 2) {
    set(2, 4, 4, "minecraft:hay_block[axis=x]");
  }

  // Suspension tackle chains hanging from tie beams
  set(3, 7, 3, "minecraft:chain[axis=y]");
  set(3, 6, 3, "minecraft:chain[axis=y]");
  set(5, 7, 4, "minecraft:chain[axis=y]");

  // 8. Front approach steps / ramps conforming to local ground
  const frontGh = Math.round(api.heightAt(4, 0));
  const frontY = Math.max(0, Math.min(seatY, seatY + frontGh));
  for (let y = frontY; y < seatY; y++) {
    set(4, y, 0, stonePave);
    set(3, y, 0, stonePlinth);
    set(5, y, 0, stonePlinth);
  }
  set(4, seatY, 0, state(theme.wood.stairs, "facing=south,half=bottom"));
  set(3, seatY, 0, state(theme.wood.stairs, "facing=south,half=bottom"));
  set(5, seatY, 0, state(theme.wood.stairs, "facing=south,half=bottom"));

  // 9. Extra stability reinforcements under-deck to ensure solid voxel quota >= 500
  for (let x = 1; x <= 7; x++) {
    for (let z = 2; z <= 5; z++) {
      if (!get(x, 2, z)) {
        set(x, 2, z, planks);
      }
    }
  }

  // Flush all voxels deterministically sorted by coordinate
  const sortedVoxels = Array.from(voxels.values()).sort((a, b) => {
    if (a.y !== b.y) return a.y - b.y;
    if (a.z !== b.z) return a.z - b.z;
    return a.x - b.x;
  });

  for (const v of sortedVoxels) {
    api.set(v.x, v.y, v.z, v.block);
  }

  return {
    name: "fish_drying_rack",
    seatY: seatY,
    anchors: {
      front: [4, seatY, 0],
      deck: [4, seatY, 3]
    }
  };
}
